INSERT INTO `chatbot_training_log` VALUES (1,'dâu tây','vi',NULL,0,'Tôi tìm thấy dữ liệu sản phẩm phù hợp:\n- Dâu tây Đà Lạt: 140.000đ/kg, tồn 20.010 kg, nhóm Trái cây\n- Mít Thái: 45.000đ/kg, tồn 20.010 kg, nhóm Trái cây\n- Thanh long ruột đỏ: 32.000đ/kg, tồn 20.010 kg, nhóm Trái cây\n- Chôm chôm Java: 55.000đ/kg, tồn 20.010 kg, nhóm Trái cây\n- Bơ sáp Đắk Lắk: 95.000đ/kg, tồn 20.010 kg, nhóm Trái cây',0,'2026-05-27 13:06:58'),(2,'giá cam sành','vi',NULL,0,'Tôi tìm thấy sản phẩm:\n- Cam sành: 30.000đ/kg, tồn 20.006 kg, nguồn gốc Vùng trồng Hòa Lộc, Cái Bè, Tiền Giang\n  Xem: /webbanhang/product/detail/12',0,'2026-05-27 13:16:03'),(3,'giá xăng','vi',NULL,0,'Tôi đang chạy AI hỗ trợ cửa hàng. Tôi ưu tiên dữ liệu nội bộ: sản phẩm, giá, tồn kho, nguồn gốc, thanh toán và đơn hàng. Tôi không tự lấy thông tin từ sàn khác hoặc web nếu bạn không hỏi rõ tin tức/thị trường.\n\nBạn có thể hỏi:\n- Giá hoặc tồn kho của một nông sản\n- Chính sách thanh toán, cọc 40-60% hoặc 100%\n- Trạng thái đơn hàng theo mã đơn\n- Giao hàng nội địa/quốc tế',1,'2026-05-27 13:22:13'),(4,'giá cam xoài lựu và mía','vi',NULL,0,'Tôi đang chạy AI hỗ trợ cửa hàng. Tôi ưu tiên dữ liệu nội bộ: sản phẩm, giá, tồn kho, nguồn gốc, thanh toán và đơn hàng. Tôi không tự lấy thông tin từ sàn khác hoặc web nếu bạn không hỏi rõ tin tức/thị trường.\n\nBạn có thể hỏi:\n- Giá hoặc tồn kho của một nông sản\n- Chính sách thanh toán, cọc 40-60% hoặc 100%\n- Trạng thái đơn hàng theo mã đơn\n- Giao hàng nội địa/quốc tế',1,'2026-05-27 13:22:30'),(5,'mía và cam','vi',NULL,0,'Tôi đang chạy AI hỗ trợ cửa hàng. Tôi ưu tiên dữ liệu nội bộ: sản phẩm, giá, tồn kho, nguồn gốc, thanh toán và đơn hàng. Tôi không tự lấy thông tin từ sàn khác hoặc web nếu bạn không hỏi rõ tin tức/thị trường.\n\nBạn có thể hỏi:\n- Giá hoặc tồn kho của một nông sản\n- Chính sách thanh toán, cọc 40-60% hoặc 100%\n- Trạng thái đơn hàng theo mã đơn\n- Giao hàng nội địa/quốc tế',1,'2026-05-27 13:22:47'),(6,'gái xoài cát','vi',NULL,0,'Tôi tìm thấy dữ liệu sả